{
  "correction_rules": [
    "Adjust forecasts downward when sentiment history includes positive sentiment (≥0.25) and model overestimates prices.",
    "Reduce forecast magnitude by 5-10% if recent true outcomes show mean reversion toward lower levels after a spike.",
    "Increase forecast lag by 1-2 days if model shows premature peak or overshoot after a recent price spike.",
    "Apply upward bias correction if true outcomes consistently exceed model forecasts during high sentiment periods.",
    "Use historical mean of last 5 days as baseline for correction if model deviates >15% from true outcome without sentiment signal.",
    "Avoid overreacting to single-day sentiment spikes; apply smoothing filter for sentiment-driven corrections."
  ]
}
